using System;using System.IO;using System.Linq;using System.Reflection;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;using KianaPet;
class SettingsQuickAccessTests {
 static int checks;static void Check(bool value,string name){if(!value)throw new Exception(name);checks++;}static object Field(object value,string name){return value.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(value);}
 static StackPanel Page(SettingsWindow w,string name){return (StackPanel)((ScrollViewer)((TabControl)Field(w,"settingsTabs")).Items.Cast<TabItem>().Single(t=>(string)t.Header==name).Content).Content;}
 static bool InViewport(FrameworkElement element,ScrollViewer scroll){var p=element.TranslatePoint(new Point(),scroll);return element.IsVisible&&p.X>=0&&p.Y>=0&&p.Y+element.ActualHeight<=scroll.ActualHeight+1;}
 [STAThread]static int Main(string[] args){Store.Root=args[0];Store.Save(new Config{LinkChatGPT=false,MusicEnabled=false,Walking=false,Gravity=false,SleepSchedule=false,IdleSleep=false,HideFullscreen=false,NoticeSound=false});var app=new Application{ShutdownMode=ShutdownMode.OnLastWindowClose};var pet=new PetWindow(true);bool passed=false;
  pet.Loaded+=async delegate{try{await Task.Delay(1100);((DispatcherTimer)Field(pet,"animation")).Stop();var w=app.Windows.OfType<SettingsWindow>().Single();string saved=File.ReadAllText(Path.Combine(Store.Root,"settings.json"));var originalLink=pet.Link.Current;var originalMusic=pet.Music.Current;
   Check(w.ActiveCategory=="常用"&&((TextBlock)Page(w,"常用").Children[0]).Text=="快捷连接","quick connections are the first section on the default page");
   var music=(Button)Field(w,"commonConnectMusic");var gpt=(Button)Field(w,"commonConnectGPT");Check(music.IsEnabled&&gpt.IsEnabled&&music.IsVisible&&gpt.IsVisible,"both direct connection entries visible");
   pet.Music.Current=new MusicState{Label="系统媒体测试状态"};pet.Link.Current=new BridgeState{Label="Hooks 测试状态"};w.UpdateStatus();Check(((TextBlock)Field(w,"commonMusicStatus")).Text.Contains("系统媒体测试状态")&&((TextBlock)Field(w,"commonGPTStatus")).Text.Length>8,"connection labels update from the providers");pet.Music.Current=originalMusic;pet.Link.Current=originalLink;w.UpdateStatus();
   w.Capture(Path.Combine(Store.Root,"common-quick-connect.png"));w.Width=760;w.Height=520;w.UpdateLayout();var commonScroll=(ScrollViewer)((TabControl)Field(w,"settingsTabs")).SelectedContent;Check(InViewport(music,commonScroll)&&InViewport(gpt,commonScroll),"both connection buttons fit the smallest window without scrolling");
   w.Width=920;w.Height=790;w.NavigateCategory("外观与互动","");await Task.Delay(180);var image=(Image)Field(w,"appearancePreviewImage");var timer=(DispatcherTimer)Field(w,"appearancePreviewTimer");var skins=(ComboBox)Field(w,"appearancePreviewSkin");var actions=(ComboBox)Field(w,"appearancePreviewAction");
   Check(image.Source!=null&&timer.IsEnabled,"appearance page has a running image preview");w.Capture(Path.Combine(Store.Root,"appearance-preview.png"));
   string oldSkin=pet.Settings.Skin;skins.SelectedValue=oldSkin=="time-runner-kiana-round"?"kiana-winter-wish-round":"time-runner-kiana-round";actions.SelectedValue="pat";await Task.Delay(180);
   Check(pet.Settings.Skin==oldSkin&&saved==File.ReadAllText(Path.Combine(Store.Root,"settings.json")),"changing preview skin and action never saves live preferences");Check(((TextBlock)Field(w,"appearancePreviewLabel")).Text.Contains("尚未应用"),"unapplied skin is labeled");Check(ReferenceEquals(originalLink,pet.Link.Current)&&ReferenceEquals(originalMusic,pet.Music.Current),"preview does not change either connection");
   var play=(Button)Field(w,"appearancePreviewPlay");play.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!timer.IsEnabled,"pause controls only preview playback");play.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(timer.IsEnabled,"preview can resume");
   skins.SelectedValue="kiana-winter-wish";Check(!actions.Items.Cast<ComboBoxItem>().Any(c=>Convert.ToString(c.Tag).StartsWith("music-")),"unsupported music poses are hidden for non-Q skins");skins.SelectedValue="time-runner-kiana-round";actions.SelectedValue="music-quiet";await Task.Delay(80);Check(image.Source!=null&&actions.Items.Cast<ComboBoxItem>().Any(c=>Convert.ToString(c.Tag)=="music-quiet"),"Q music preview reuses existing frames");
   var apply=SettingsWindow.Descendants<Button>(Page(w,"外观与互动")).Single(b=>(string)b.Content=="应用这套衣装");apply.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(pet.Settings.Skin=="time-runner-kiana-round"&&Store.Load().Skin==pet.Settings.Skin,"only explicit apply changes and saves the outfit");
   w.NavigateCategory("常用","");Check(!timer.IsEnabled,"leaving the appearance page stops its timer");w.NavigateCategory("外观与互动","");await Task.Delay(80);Check(timer.IsEnabled,"returning resumes the preview");
   pet.Settings.ReduceMotion=true;pet.ApplySettings();w.UpdateStatus();Check(!timer.IsEnabled&&image.Source!=null,"reduced motion keeps a static preview");pet.Settings.ReduceMotion=false;pet.ApplySettings();w.UpdateStatus();
   pet.Settings.Theme="dark";w.RefreshTheme();w.UpdateStatus();w.Width=760;w.Height=520;w.UpdateLayout();w.Capture(Path.Combine(Store.Root,"appearance-preview-small-dark.png"));
   w.NavigateCategory("常用","连接网易云");Check(music.IsVisible,"search retains the direct music connection");w.NavigateCategory("外观与互动","预览");Check(((Border)Field(w,"appearancePreviewSurface")).IsVisible,"search exposes the preview section");w.Close();Check(!timer.IsEnabled,"closing settings releases the preview timer");passed=true;
  }catch(Exception e){Store.Atomic("error.json",new{error=e.ToString()});}finally{Store.Atomic("result.json",new{passed,checks});foreach(var w in app.Windows.Cast<Window>().Where(w=>w!=pet).ToArray())w.Close();pet.Close();}};app.Run(pet);return passed?0:1;
 }
}
